"""Truncates a string after a certain number of characters.

    :type s: str
    :param s: string to be truncated
    :type length: int
    :param length: max number of characters
    :rtype: str
    :return: truncated string"""
def cutoff(s: Any, length: Any) -> object {
    if (len(s) < (length - 2)) {
        return s;
    }
    return ("%s.." % s[0:(length - 2)]);
}

"""
    Return the length of the longest commmon sequence for all subseq starting at
    index indices[0], indices[1], ....etc
    """
def max_common_sequence_length(seq: Any, indices: Any, cur_size: Any) -> object {
    seqlen = len(seq);
    j = cur_size + 1;
    while (j < (seqlen - indices[-1])) {
        firstnt = seq[(indices[0] + j)];
        if not all((seq[(i + j)] == firstnt) for i in indices[1:]) {
            return j;
        }
        j += 1;
    }
    return j;
}

